<?php/** * Service: Media Detection — V1.0.4 * * Handles local-first AI detection for media items, metadata extraction (EXIF/C2PA), * IPTC header writing, and Media Library integration. * * @package MegaGovern * @version 1.0.4 */namespace MegaGovern;if ( ! defined( 'ABSPATH' ) ) {	exit;}/** * Class Media * * Handles media AI detection, metadata extraction, and Media Library integration. */class Media {	/**	 * AI keywords for detection.	 *	 * @var array	 */	private const AI_KEYWORDS = array(		'midjourney',		'dall-e',		'stable diffusion',		'stablediffusion',		'comfyui',		'automatic1111',		'generative fill',		'firefly',		'flux',		'sora',		'recraft',		'ideogram',		'novelai',		'fooocus',		'runway',		'pika',		'luma',	);	/**	 * Constructor — checks table existence before registering hooks.	 */	public function __construct() {		// Check if required tables exist before registering hooks		if ( ! $this->tables_exist() ) {			// Tables don't exist yet — skip hook registration to prevent errors			return;		}		add_filter( 'attachment_fields_to_edit', array( $this, 'add_attachment_declaration_fields' ), 10, 2 );		add_filter( 'attachment_fields_to_save', array( $this, 'save_attachment_declaration_fields' ), 10, 2 );		add_filter( 'manage_media_columns', array( $this, 'add_media_columns' ) );		add_action( 'manage_media_custom_column', array( $this, 'render_media_column' ), 10, 2 );		add_action( 'add_attachment', array( $this, 'auto_scan_media_on_upload' ) );		add_filter( 'wp_generate_attachment_metadata', array( $this, 'embed_iptc_metadata_on_generation' ), 10, 2 );		add_action( 'add_meta_boxes', array( $this, 'register_binary_inspector_box' ) );	}	// ═══════════════════════════════════════	// TABLE EXISTENCE	// ═══════════════════════════════════════	/**	 * Check if required tables exist.	 *	 * @return bool	 */	private function tables_exist(): bool {		global $wpdb;		$required_tables = array(			$wpdb->prefix . 'posts',			$wpdb->prefix . 'postmeta',		);		foreach ( $required_tables as $table ) {			// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching			$exists = $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $table ) );			if ( empty( $exists ) ) {				return false;			}		}		return true;	}	// ═══════════════════════════════════════	// ANALYSIS	// ═══════════════════════════════════════	/**	 * Analyze an image for AI markers.	 *	 * @param int $attachment_id Attachment ID.	 * @return array Analysis results.	 */	public function analyze( $attachment_id ) {		$file_path = get_attached_file( $attachment_id );		if ( ! $file_path || ! file_exists( $file_path ) ) {			return array(				'confidence' => 0,				'markers'    => array(),				'suggested'  => 'human',			);		}		$mime_type = get_post_mime_type( $attachment_id );		$markers   = array();		// 1. C2PA JUMBF Box — precise		$has_c2pa = $this->check_c2pa_manifest( $file_path );		if ( $has_c2pa ) {			$markers[] = 'c2pa_manifest_found';		}		// 2. EXIF		$exif_markers = $this->check_exif_data( $file_path );		if ( ! empty( $exif_markers ) ) {			$markers = array_merge( $markers, $exif_markers );		}		// 3. PNG chunks		if ( 'image/png' === $mime_type ) {			$png_markers = $this->check_png_chunks( $file_path );			if ( ! empty( $png_markers ) ) {				$markers = array_merge( $markers, $png_markers );			}		}		$confidence = 0;		$suggested  = 'human';		if ( in_array( 'c2pa_manifest_found', $markers, true ) ) {			$confidence = 95;			$suggested  = 'ai_generated';		} elseif ( ! empty( $markers ) ) {			$confidence = 85;			$suggested  = 'ai_generated';		}		$result = array(			'confidence' => $confidence,			'markers'    => array_values( array_unique( $markers ) ),			'suggested'  => $suggested,			'scanned_at' => current_time( 'mysql' ),		);		update_post_meta( $attachment_id, '_megagovern_media_detection', $result );		// Write provenance meta for Reports.php precise query		$provenance = array(			'c2pa_manifest_found' => (bool) $has_c2pa,			'c2pa_manifest'       => $has_c2pa ? 'detected' : 'none',			'markers'             => $result['markers'],			'confidence'          => $confidence,			'scanned_at'          => current_time( 'mysql' ),		);		update_post_meta( $attachment_id, '_megagovern_upload_provenance', wp_json_encode( $provenance, JSON_UNESCAPED_SLASHES ) );		return $result;	}	// ═══════════════════════════════════════	// C2PA DETECTION	// ═══════════════════════════════════════	/**	 * Precise C2PA JUMBF detection — validates box structure.	 *	 * @param string $file_path Path to image file.	 * @return bool True if C2PA manifest found.	 */	private function check_c2pa_manifest( $file_path ) {		global $wp_filesystem;				// Initialize WP_Filesystem		if ( ! function_exists( 'WP_Filesystem' ) ) {			require_once ABSPATH . 'wp-admin/includes/file.php';		}		WP_Filesystem();				if ( $wp_filesystem && $wp_filesystem->exists( $file_path ) ) {			$content = $wp_filesystem->get_contents( $file_path );			if ( false !== $content && ! empty( $content ) ) {				$chunk = substr( $content, 0, 65536 );				$lower = strtolower( $chunk );								// Precise signatures — JUMBF + C2PA				$has_jumbf = false !== strpos( $lower, 'jumbf' );				$has_c2pa  = false !== strpos( $lower, 'c2pa' );				// Must have JUMBF box AND one of the C2PA identifiers to avoid false positives				if ( $has_jumbf && $has_c2pa ) {					// Additional precise atoms					if ( false !== strpos( $lower, 'c2pa.manifest' ) ||						 false !== strpos( $lower, 'c2pa.assertion' ) ||						 false !== strpos( $lower, 'urn:c2pa' ) ||						 false !== strpos( $lower, 'c2pa.ingredient' ) ) {						return true;					}					// Fallback: jumbf + c2pa together is already strong signal					return true;				}			}		}				return false;	}	// ═══════════════════════════════════════	// EXIF & PNG DETECTION	// ═══════════════════════════════════════	/**	 * Check EXIF data for AI markers.	 *	 * @param string $file_path Path to image file.	 * @return array Detected markers.	 */	private function check_exif_data( $file_path ) {		$markers = array();		if ( ! function_exists( 'exif_read_data' ) ) {			return $markers;		}		// phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged		$exif = @exif_read_data( $file_path );		if ( ! $exif || ! is_array( $exif ) ) {			return $markers;		}		$searchable = '';		if ( isset( $exif['Software'] ) ) {			$searchable .= ' ' . $exif['Software'];		}		if ( isset( $exif['ImageDescription'] ) ) {			$searchable .= ' ' . $exif['ImageDescription'];		}		if ( isset( $exif['Artist'] ) ) {			$searchable .= ' ' . $exif['Artist'];		}		if ( isset( $exif['UserComment'] ) ) {			$searchable .= ' ' . $exif['UserComment'];		}		$searchable = strtolower( $searchable );		foreach ( self::AI_KEYWORDS as $keyword ) {			if ( false !== strpos( $searchable, $keyword ) ) {				$markers[] = 'exif_keyword_' . sanitize_key( $keyword );			}		}		return $markers;	}	/**	 * Check PNG chunks for AI markers.	 *	 * @param string $file_path Path to image file.	 * @return array Detected markers.	 */	private function check_png_chunks( $file_path ) {		$markers = array();		global $wp_filesystem;				if ( ! function_exists( 'WP_Filesystem' ) ) {			require_once ABSPATH . 'wp-admin/includes/file.php';		}		WP_Filesystem();				if ( $wp_filesystem && $wp_filesystem->exists( $file_path ) ) {			$content = $wp_filesystem->get_contents( $file_path );			if ( false !== $content && ! empty( $content ) ) {				$header = substr( $content, 0, 16384 );				$header_lower = strtolower( $header );				if ( false !== strpos( $header_lower, 'parameters' ) ||					 false !== strpos( $header_lower, 'prompt' ) ||					 false !== strpos( $header_lower, 'workflow' ) ) {					foreach ( self::AI_KEYWORDS as $keyword ) {						if ( false !== strpos( $header_lower, $keyword ) ) {							$markers[] = 'png_chunk_' . sanitize_key( $keyword );						}					}				}			}		}		return $markers;	}	// ═══════════════════════════════════════	// AUTO SCAN & IPTC	// ═══════════════════════════════════════	/**	 * Auto-scan media on upload.	 *	 * @param int $attachment_id Attachment ID.	 */	public function auto_scan_media_on_upload( $attachment_id ) {		$scan = $this->analyze( $attachment_id );		if ( ! empty( $scan['suggested'] ) && 'human' !== $scan['suggested'] ) {			update_post_meta( $attachment_id, '_megagovern_declaration', sanitize_key( $scan['suggested'] ) );			update_post_meta( $attachment_id, '_megagovern_declared_by', get_current_user_id() );			update_post_meta( $attachment_id, '_megagovern_declared_at', current_time( 'mysql' ) );		} else {			update_post_meta( $attachment_id, '_megagovern_declaration', 'human' );		}	}	/**	 * Embed IPTC metadata on image generation.	 *	 * @param array $metadata      Attachment metadata.	 * @param int   $attachment_id Attachment ID.	 * @return array Modified metadata.	 */	public function embed_iptc_metadata_on_generation( $metadata, $attachment_id ) {		$declaration = get_post_meta( $attachment_id, '_megagovern_declaration', true );		if ( empty( $declaration ) || 'human' === $declaration ) {			return $metadata;		}		$file_path = get_attached_file( $attachment_id );		$mime_type = get_post_mime_type( $attachment_id );		if ( 'image/jpeg' !== $mime_type || ! file_exists( $file_path ) || ! function_exists( 'iptcembed' ) ) {			return $metadata;		}		$iptc_url = 'http://cv.iptc.org/newscodes/digitalsourcetype/trainedAlgorithmicMedia';		if ( 'ai_assisted' === $declaration ) {			$iptc_url = 'http://cv.iptc.org/newscodes/digitalsourcetype/compositeWithTrainedAlgorithmicMedia';		}		$iptc_data = "\x1C\x02\xA4" . chr( strlen( $iptc_url ) ) . $iptc_url;		// phpcs:ignore WordPress.PHP.NoSilencedErrors.Discouraged		$content = @iptcembed( $iptc_data, $file_path, 0 );		if ( false !== $content ) {			global $wp_filesystem;			if ( ! function_exists( 'WP_Filesystem' ) ) {				require_once ABSPATH . 'wp-admin/includes/file.php';			}			WP_Filesystem();						if ( $wp_filesystem ) {				$wp_filesystem->put_contents( $file_path, $content );			}			update_post_meta( $attachment_id, '_megagovern_iptc_synced', 1 );		}		return $metadata;	}	// ═══════════════════════════════════════	// MEDIA LIBRARY INTEGRATION	// ═══════════════════════════════════════	/**	 * Add declaration fields to attachment edit screen.	 *	 * @param array  $form_fields Form fields.	 * @param object $post        Post object.	 * @return array Modified form fields.	 */	public function add_attachment_declaration_fields( $form_fields, $post ) {		$current = get_post_meta( $post->ID, '_megagovern_declaration', true );		if ( ! $current ) {			$current = 'human';		}		$scan = get_post_meta( $post->ID, '_megagovern_media_detection', true );		$options = array(			'human'        => __( 'Human Created', 'megagovern' ),			'ai_assisted'  => __( 'AI Modified', 'megagovern' ),			'ai_generated' => __( 'AI Generated', 'megagovern' ),			'deepfake'     => __( 'Synthetic Media', 'megagovern' ),		);		$html = '<select name="attachments[' . $post->ID . '][megagovern_declaration]" id="attachments-' . $post->ID . '-megagovern_declaration" class="widefat">';		foreach ( $options as $key => $label ) {			$html .= '<option value="' . esc_attr( $key ) . '" ' . selected( $current, $key, false ) . '>' . esc_html( $label ) . '</option>';		}		$html .= '</select>';		if ( ! empty( $scan['confidence'] ) ) {			$html .= '<p class="description" style="margin-top:5px;">';			$html .= sprintf(				/* translators: 1: confidence percentage, 2: scan timestamp */				esc_html__( 'Local Scan: %1$d%% AI likelihood (%2$s)', 'megagovern' ),				(int) $scan['confidence'],				isset( $scan['scanned_at'] ) ? esc_html( $scan['scanned_at'] ) : ''			);			$html .= '</p>';		}		$form_fields['megagovern_declaration'] = array(			'label' => __( 'AI Governance', 'megagovern' ),			'input' => 'html',			'html'  => $html,		);		return $form_fields;	}	/**	 * Save attachment declaration fields.	 *	 * @param array $post        Post data.	 * @param array $attachment Attachment data.	 * @return array Modified post data.	 */	public function save_attachment_declaration_fields( $post, $attachment ) {		if ( isset( $attachment['megagovern_declaration'] ) ) {			$val     = sanitize_key( $attachment['megagovern_declaration'] );			$allowed = array( 'human', 'ai_assisted', 'ai_generated', 'deepfake' );			if ( in_array( $val, $allowed, true ) ) {				update_post_meta( $post['ID'], '_megagovern_declaration', $val );				update_post_meta( $post['ID'], '_megagovern_declared_by', get_current_user_id() );				update_post_meta( $post['ID'], '_megagovern_declared_at', current_time( 'mysql' ) );				if ( 'human' !== $val ) {					$this->embed_iptc_metadata_on_generation( array(), $post['ID'] );				}			}		}		return $post;	}	/**	 * Add AI Declaration column to Media Library.	 *	 * @param array $columns Existing columns.	 * @return array Modified columns.	 */	public function add_media_columns( $columns ) {		$columns['megagovern_ai'] = __( 'AI Declaration', 'megagovern' );		return $columns;	}	/**	 * Render AI Declaration column in Media Library.	 *	 * @param string $column  Column name.	 * @param int    $post_id Post ID.	 */	public function render_media_column( $column, $post_id ) {		if ( 'megagovern_ai' !== $column ) {			return;		}		$declaration = get_post_meta( $post_id, '_megagovern_declaration', true );		if ( ! $declaration ) {			$declaration = 'human';		}		$labels = array(			'human'        => array(				'label' => __( 'Human', 'megagovern' ),				'class' => 'mga-badge-human',			),			'ai_assisted'  => array(				'label' => __( 'AI Modified', 'megagovern' ),				'class' => 'mga-badge-assisted',			),			'ai_generated' => array(				'label' => __( 'AI Generated', 'megagovern' ),				'class' => 'mga-badge-generated',			),			'deepfake'     => array(				'label' => __( 'Synthetic', 'megagovern' ),				'class' => 'mga-badge-deepfake',			),		);		$info = isset( $labels[ $declaration ] ) ? $labels[ $declaration ] : $labels['human'];		echo '<span class="mga-badge ' . esc_attr( $info['class'] ) . '">' . esc_html( $info['label'] ) . '</span>';	}	// ═══════════════════════════════════════	// BINARY INSPECTOR	// ═══════════════════════════════════════	/**	 * Register binary inspector meta box.	 */	public function register_binary_inspector_box() {		add_meta_box(			'megagovern_binary_inspector',			__( '🔍 MegaGovern — C2PA & Binary Header Inspector', 'megagovern' ),			array( $this, 'render_binary_inspector_box' ),			'attachment',			'normal',			'high'		);	}	/**	 * Render binary inspector meta box.	 *	 * @param object $post Post object.	 */	public function render_binary_inspector_box( $post ) {		$scan = get_post_meta( $post->ID, '_megagovern_media_detection', true );		$prov = get_post_meta( $post->ID, '_megagovern_upload_provenance', true );		$file_path = get_attached_file( $post->ID );		$has_c2pa  = $file_path ? $this->check_c2pa_manifest( $file_path ) : false;		$prov_data = json_decode( $prov, true );		?>		<div style="background: #111827; color: #10B981; padding: 16px; border-radius: 8px; font-family: monospace; font-size: 13px; line-height: 1.6; direction: ltr;">			<div style="color: #F3F4F6; font-weight: bold; margin-bottom: 8px; border-bottom: 1px solid #374151; padding-bottom: 4px;">				[Local C2PA & Media Binary Analysis — Precise Mode]			</div>			<p style="margin: 4px 0;">				<strong>C2PA Manifest Status:</strong>				<?php if ( $has_c2pa ) : ?>					<span style="color: #34D399; font-weight: bold;">✅ Valid Manifest Stream Detected (JUMBF + c2pa.manifest)</span>				<?php else : ?>					<span style="color: #9CA3AF;">❌ No C2PA Manifest Found</span>				<?php endif; ?>			</p>			<?php if ( ! empty( $scan['markers'] ) ) : ?>				<p style="margin: 4px 0; color: #FBBF24;">					<strong>Matched Binary Markers:</strong> <?php echo esc_html( implode( ', ', $scan['markers'] ) ); ?>				</p>			<?php endif; ?>			<p style="margin: 4px 0; color: #9CA3AF;">				<strong>Stored Provenance JSON:</strong> <?php echo $prov ? esc_html( $prov ) : 'none'; ?>				<?php if ( $prov_data && isset( $prov_data['c2pa_manifest_found'] ) && true === $prov_data['c2pa_manifest_found'] ) : ?>					<span style="color:#34D399;"> — precise match ✅</span>				<?php endif; ?>			</p>			<p style="margin: 4px 0; color: #9CA3AF;">				<strong>IPTC Synchronized:</strong> <?php echo get_post_meta( $post->ID, '_megagovern_iptc_synced', true ) ? 'YES (Tag 2#164 Written)' : 'NO'; ?>			</p>		</div>		<?php	}}